#!/usr/bin/env python3
"""Build V12 books-on-the-exact-plant-shelf review draft."""
from __future__ import annotations
import hashlib,json
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]; RECIPE_PATH=ROOT/'data/kitchen_kettle_recipe_shelf_v12_recipe.json'; RECIPE=json.loads(RECIPE_PATH.read_text())
SOURCE=ROOT/'art/source/kitchen-kettle-recipe-shelf-2026-10-17-v12'; V7=ROOT/'art/raw/kitchen-room-flat-cutaway-2026-10-16-v7'; V10=ROOT/'art/raw/kitchen-porthole-backdrop-cutout-2026-10-17-v10'; V11=ROOT/'art/raw/kitchen-kettle-recipe-shelf-2026-10-17-v11'; RAW=ROOT/'art/raw/kitchen-kettle-recipe-shelf-2026-10-17-v12'; DRAFT=ROOT/'art/drafts/kitchen-kettle-recipe-shelf-2026-10-17-v12'; PUBLIC=ROOT/'public/keeper-review/kitchen-kettle-recipe-shelf-v12'; ASSETS=PUBLIC/'assets'
D=4;BAY=21;DATUM=4;FOOT=52
def px(v):return round(v*D)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def tree(d):
 h=hashlib.sha256()
 for p in sorted(x for x in d.rglob('*') if x.is_file()):h.update(p.relative_to(d).as_posix().encode());h.update(b'\0');h.update(p.read_bytes());h.update(b'\0')
 return h.hexdigest()
def save(im,p):p.parent.mkdir(parents=True,exist_ok=True);im.save(p,optimize=False,compress_level=9)
def bound(im):
 b=im.getchannel('A').getbbox();return {"xLp":b[0]/4,"yLp":b[1]/4,"widthLp":(b[2]-b[0])/4,"heightLp":(b[3]-b[1])/4}
def build_shelf():
 im=Image.open(SOURCE/'plant-shelf-books-edit.png').convert('RGBA');im.putalpha(im.getchannel('A').point(lambda v:255 if v>=96 else 0));im=im.crop(im.getchannel('A').getbbox());im=im.resize((px(19),px(9.75)),Image.Resampling.LANCZOS);im.putalpha(im.getchannel('A').point(lambda v:255 if v>=96 else 0));out=Image.new('RGBA',(px(21),px(56)),(0,0,0,0));out.alpha_composite(im,(px(1),px(25)-im.height))
 plant=Image.open(V10/'obj_fridge_wall_shelf_v10_f1.png').convert('RGBA');out.paste((0,0,0,0),(0,83,84,100));out.alpha_composite(plant.crop((0,83,84,100)),(0,83));return out
def asset(name,im,logical,extra=None):
 p=RAW/f'{name}.png';save(im,p);m={"w":logical[0],"h":logical[1],"frames":1,"fps":0,"density":4,"anchor":[logical[0]/2,logical[1]],"projection":{"id":"flat-cutaway-v1","runtimeDepthScaling":False}};m.update(extra or {});p.with_suffix('.json').write_text(json.dumps(m,indent=2)+'\n');rp=ASSETS/f'{name}.png';save(im,rp);return {"png":p.relative_to(ROOT).as_posix(),"json":p.with_suffix('.json').relative_to(ROOT).as_posix(),"sha256":sha(p),"meta":m,"bound":bound(im),"url":f'/keeper-review/kitchen-kettle-recipe-shelf-v12/assets/{name}.png'}
def child(o,i,b):o.alpha_composite(i,(px(DATUM+(b-1)*BAY),0))
def kettle(o,i,b):o.alpha_composite(i,(px(DATUM+(b-1)*BAY),px(FOOT)-i.height))
def page(data):
 h='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kitchen V12 · plant-shelf-standard books</title><style>:root{color-scheme:dark;--b:#06131c;--p:#102630;--c:#091b24;--l:#365663;--i:#f7f1dd;--g:#efb64d}*{box-sizing:border-box}body{margin:0;background:var(--b);color:var(--i);font:16px/1.48 system-ui}header,main{max-width:1520px;margin:auto;padding:22px}.tag{display:inline-block;border:1px solid var(--g);border-radius:99px;padding:5px 10px;margin-right:7px;color:#ffd98a}.panel{background:var(--p);border:1px solid var(--l);border-radius:14px;padding:16px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:14px}.card{background:var(--c);border:1px solid var(--l);border-radius:11px;padding:12px}.well{overflow:auto;padding:10px;background:repeating-conic-gradient(#172c36 0 25%,#10232d 0 50%) 0/18px 18px;border-radius:9px}.well img{display:block;height:224px;width:auto}.notice{border-left:4px solid var(--g);background:#2a2518;padding:12px}select{background:#17323e;color:var(--i);padding:7px;border:1px solid #627d87;border-radius:7px}table{width:100%;border-collapse:collapse}th,td{padding:7px;border-bottom:1px solid var(--l);text-align:left}</style></head><body><header><span class="tag">Draft only</span><span class="tag">V10 shelf structure exact</span><h1>Kitchen V12 · books on the plant-shelf standard</h1><p>Only the contents change. The final plank and brackets are byte-identical to the established plant shelf.</p><p id="loading" class="notice">Preloading review media…</p></header><main><section class="panel"><h2>Structural standard versus replacement</h2><div class="grid"><div class="card"><h3>V10 plant shelf standard</h3><div class="well"><img id="standard"></div></div><div class="card"><h3>V12 books and jar bookends</h3><div class="well"><img id="shelf"></div></div></div></section><section class="panel"><h2>Room comparison</h2><div class="grid"><div class="card"><h3>Rejected V11</h3><div class="well"><img id="before"></div></div><div class="card"><h3>V12 at matched scale</h3><div class="well"><img id="after"></div></div></div></section><section class="panel"><h2>Shared kettle transform</h2><label>Bay <select id="bay" disabled><option>2</option><option>5</option><option>8</option></select></label><div class="well"><img id="move"></div></section><section class="panel"><h2>Measured hand-back</h2><table><tbody id="rows"></tbody></table><p class="notice">Review-only. Nothing is approved, promoted or wired.</p></section></main><script>const D=__D__,u=[];const c=v=>{if(typeof v==='string'&&v.startsWith('/keeper-review/'))u.push(v);else if(Array.isArray(v))v.forEach(c);else if(v&&typeof v==='object')Object.values(v).forEach(c)};c(D);const a=[...new Set(u)];function go(){standard.src=D.standard;shelf.src=D.shelf;before.src=D.before;after.src=D.after;bay.disabled=false;bay.value='5';const s=()=>move.src=D.moves[bay.value];bay.onchange=s;s();for(const r of D.rows){const t=document.createElement('tr');t.innerHTML=`<th>${r.name}</th><td>${r.value}</td>`;rows.append(t)}loading.textContent=`All ${a.length} unique images loaded and decoded.`}Promise.all(a.map(src=>new Promise((ok,bad)=>{const i=new Image;i.onload=()=>i.decode?i.decode().then(ok,bad):ok();i.onerror=bad;i.src=src}))).then(go).catch(e=>loading.textContent=e.message)</script></body></html>''';PUBLIC.mkdir(parents=True,exist_ok=True);(PUBLIC/'index.html').write_text(h.replace('__D__',json.dumps(data,separators=(',',':'))))
def main():
 for d in (RAW,DRAFT,ASSETS):
  d.mkdir(parents=True,exist_ok=True)
  for p in d.iterdir():
   if p.is_file():p.unlink()
 shelf=build_shelf();sr=asset('obj_kettle_recipe_shelf_v12_f1',shelf,(21,56),{"parent":"obj_kettle","movesWithParent":True,"interactionSpot":None,"structuralRowsPx":[83,100]});standard=Image.open(V10/'obj_fridge_wall_shelf_v10_f1.png').convert('RGBA');st=asset('v10_plant_shelf_structure_standard',standard,(21,56),{"reviewBaseline":True});before=Image.open(V11/'room_kitchen_9bay_v11_recipe_shelf.png').convert('RGBA');br=asset('room_kitchen_9bay_v11_rejected',before,(193,56),{"reviewBaseline":True});base=Image.open(V10/'room_kitchen_9bay_true_backdrop_opening.png').convert('RGBA');after=base.copy();child(after,shelf,3);ar=asset('room_kitchen_9bay_v12_recipe_shelf',after,(193,56),{"reviewComposite":True,"kettleBay":3});k=Image.open(V10/'kettle_standard.png').convert('RGBA');moves={}
 for b in RECIPE['movementProofBays']:
  r=Image.open(V7/'room_kitchen_shell_9bay.png').convert('RGBA');child(r,shelf,b);kettle(r,k,b);moves[str(b)]=asset(f'kettle_recipe_shelf_v12_move_bay_{b}',r,(193,56),{"kettleBay":b,"shelfBay":b})
 data={"standard":st['url'],"shelf":sr['url'],"before":br['url'],"after":ar['url'],"moves":{x:y['url'] for x,y in moves.items()},"rows":[{"name":"opaque bound","value":f"{sr['bound']['widthLp']} × {sr['bound']['heightLp']} lp"},{"name":"shelf bottom","value":"25 lp from room top, matching V10"},{"name":"structure","value":"rows 83–99 byte-identical to V10 plant shelf"}]};cat={"version":12,"status":"reversible-draft","recipe":RECIPE,"shelf":sr,"standard":st,"before":br,"after":ar,"moves":moves,"movementPlacementsLp":{str(b):{"kettleXLp":DATUM+(b-1)*BAY,"shelfXLp":DATUM+(b-1)*BAY} for b in RECIPE['movementProofBays']}};(DRAFT/'asset-catalogue.json').write_text(json.dumps(cat,indent=2)+'\n');(DRAFT/'review-data.json').write_text(json.dumps(data,indent=2)+'\n');page(data);outs=sorted(p for p in RAW.iterdir() if p.is_file())+sorted(DRAFT.glob('*.json'))+[PUBLIC/'index.html'];reg={"version":12,"status":"reversible-draft","scope":"plant-shelf-structure-books-only","runtimeChanged":False,"keeperChanged":False,"finalChanged":False,"v10Overwritten":False,"v11Overwritten":False,"protectedSnapshots":{"kitchenV10":tree(V10),"kitchenV11":tree(V11),"runtimeSpriteManifest":sha(ROOT/'public/sprites/manifest.json')},"outputs":[{"path":p.relative_to(ROOT).as_posix(),"sha256":sha(p)} for p in outs]};(DRAFT/'batch-register.json').write_text(json.dumps(reg,indent=2)+'\n');print(json.dumps({"set":RECIPE['id'],"bound":sr['bound'],"review":PUBLIC.relative_to(ROOT).as_posix()},indent=2))
if __name__=='__main__':main()
